-- Local dev data snapshot.
-- Data-only INSERTs for local dev/test data so a fresh clone has working sample records.
-- Apply after all schema files in database/, in the order documented in setup.md (same php -r pattern documented in CLAUDE.md).
-- Excludes tables already seeded by their own phaseN file: barangays (phase16),
-- zoning_use_regulations (phase15), housing_projects (phase18_housing_projects_seed).
-- Excludes buildings and subdivisions (OSM-imported GIS bulk data, 70k+/300+ rows --
-- regenerate locally via scripts/import/import-osm-buildings.php and import-osm-subdivisions.php instead).
-- citizen_accounts rows are included with password_hash and password_set_token stripped to NULL;
-- use the citizen app's set-password/forgot-password flow to set a working password locally.

SET FOREIGN_KEY_CHECKS=0;



SET FOREIGN_KEY_CHECKS=1;
